import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"用户自定义变量","description":"","frontmatter":{},"headers":[],"relativePath":"translation/Custom_Variable.md","filePath":"translation/Custom_Variable.md"}`),a={name:`translation/Custom_Variable.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="用户自定义变量" tabindex="-1">用户自定义变量 <a class="header-anchor" href="#用户自定义变量" aria-label="Permalink to “用户自定义变量”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/UserVars" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/UserVars</a></p></blockquote><p>使用预处理指令 <code>#DIM</code> 和 <code>#DIMS</code> 可以定义任意变量。</p><p>在函数中定义的变量是私有变量，只能在该函数中使用；而在<a href="./Header_File.html">头文件（ERH）</a>中定义的变量是广域变量，可以从 <code>ERB</code> 的任何位置引用。</p><h2 id="私有变量的书写格式" tabindex="-1">私有变量的书写格式 <a class="header-anchor" href="#私有变量的书写格式" aria-label="Permalink to “私有变量的书写格式”">​</a></h2><p>在想要定义变量的函数声明之下，按下面的格式书写：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#D4D4D4;">#</span><span style="color:#DCDCAA;">DIM</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">S</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">&lt;</span><span style="color:#9CDCFE;">变量名</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#E6E6E6;">, </span><span style="color:#D4D4D4;">&lt;</span><span style="color:#9CDCFE;">元素数</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#E6E6E6;"> {, </span><span style="color:#D4D4D4;">&lt;</span><span style="color:#9CDCFE;">元素数</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#E6E6E6;"> {, </span><span style="color:#D4D4D4;">&lt;</span><span style="color:#9CDCFE;">元素数</span><span style="color:#D4D4D4;">&gt;</span><span style="color:#E6E6E6;">}}</span></span></code></pre></div><ul><li><code>&lt;变量名&gt;</code> 与函数名一样，是不以数字开头、除 <code>_</code> 以外不含其他符号的任意字符串。</li><li><code>&lt;元素数&gt;</code> 是 1 到 1000000 范围内的任意整数或常数表达式，省略时为 1。</li><li>根据给出的 <code>&lt;元素数&gt;</code> 的个数，变量会被定义为不同的维度，最高为 3 维，不能定义超过 4 维的变量。</li><li>变量可以按 <code>&lt;元素数&gt;</code> 指定的数量进行赋值，并且不会被保存。初始值为 0 或空字符串。</li></ul><p>在一个函数中可以定义多个 <code>#DIM(S)</code> 私有变量。</p><p>用 <code>#DIM</code> 定义的是数值型变量，用 <code>#DIMS</code> 定义的是字符串型变量。</p><p>用 <code>#DIM(S)</code> 定义的变量还可以作为函数的参数使用，也可以为其指定初始值。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">FIND_CSTR</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">KEY</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">VALUE</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">FUNCTION</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> LCOUNT</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> KEY</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIMS</span><span style="color:#9CDCFE;"> VALUE</span></span>
<span class="line"><span style="color:#C586C0;">SIF</span><span style="color:#9CDCFE;"> KEY</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#B5CEA8;"> 0</span><span style="color:#D4D4D4;"> ||</span><span style="color:#9CDCFE;"> KEY</span><span style="color:#D4D4D4;"> &gt;=</span><span style="color:#DCDCAA;"> VARSIZE</span><span style="color:#E6E6E6;">(</span><span style="color:#CE9178;">&quot;CSTR&quot;</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#C586C0;">  RETURNF</span><span style="color:#D4D4D4;"> -</span><span style="color:#B5CEA8;">1</span></span>
<span class="line"><span style="color:#C586C0;">FOR</span><span style="color:#9CDCFE;"> LCOUNT</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">CHARANUM</span></span>
<span class="line"><span style="color:#C586C0;">  SIF</span><span style="color:#9CDCFE;"> LCOUNT</span><span style="color:#D4D4D4;"> ==</span><span style="color:#9CDCFE;"> MASTER</span></span>
<span class="line"><span style="color:#C586C0;">    CONTINUE</span></span>
<span class="line"><span style="color:#C586C0;">  SIF</span><span style="color:#9CDCFE;"> CSTR</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">LCOUNT</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">KEY</span><span style="color:#D4D4D4;"> ==</span><span style="color:#9CDCFE;"> VALUE</span></span>
<span class="line"><span style="color:#C586C0;">    RETURNF</span><span style="color:#9CDCFE;"> LCOUNT</span></span>
<span class="line"><span style="color:#C586C0;">NEXT</span></span></code></pre></div><p>如上例所示，根据变量的用途来命名，并设置合适的元素数量，可以代替不连续的 <code>LOCAL</code> 使用，从而提高可读性。</p><h2 id="初始值的设定" tabindex="-1">初始值的设定 <a class="header-anchor" href="#初始值的设定" aria-label="Permalink to “初始值的设定”">​</a></h2><p>声明一维数组变量时，可以同时定义初始值。</p><p>如果省略了数组的元素数，则初始值的个数会自动成为数组的元素数。</p><p>如果没有省略数组的元素数，则该数字就是数组的元素数。</p><p>如果没有省略元素数，而初始值的个数大于元素数，则会发生错误。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;省略了元素数，因此 HOGE 的元素数为 3</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> HOGE</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">;没有省略元素数，因此 PUGE 的元素数为 100</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> PUGE</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">100</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 4</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">5</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">6</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">;错误（初始值的个数大于指定的元素数）</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> HIGE</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">1</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 7</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">8</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">9</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">;字符串变量也可以（用字符串表达式指定）</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIMS</span><span style="color:#9CDCFE;"> SHOGE</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;A&quot;</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;B&quot;</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;C&quot;</span></span></code></pre></div><p>注意，多维数组不能定义初始值。</p><h2 id="动态变量" tabindex="-1">动态变量 <a class="header-anchor" href="#动态变量" aria-label="Permalink to “动态变量”">​</a></h2><p>像 <code>#DIM(S) DYNAMIC &lt;变量名&gt;, &lt;元素数&gt;</code> 这样在变量名前加上 <code>DYNAMIC</code>，定义的变量就会被动态分配。</p><p>具体来说，变量在函数被调用时分配，在函数结束时变量及其值都会消失。</p><p>（由于 <code>RESTART</code> 指令是「返回到函数开头」的指令，即使是动态分配的变量也不会被重置。）</p><p>即使在函数中调用自己（递归），变量也会按递归的次数分别分配，因此递归处理的行为是稳定的。</p><p>不过，它比不加 <code>DYNAMIC</code>（静态变量）时运行得更慢。</p><h2 id="常量" tabindex="-1">常量 <a class="header-anchor" href="#常量" aria-label="Permalink to “常量”">​</a></h2><p>声明一维数组变量时，在变量名前加上 <code>CONST</code> 可以定义一维数组常量。</p><p>与初始值一样，只能定义一维数组变量。</p><p>常量在声明时必须给出初始值，并且不能通过赋值来改变。</p><p>由于其性质，<code>CONST</code> 不能与 <code>GLOBAL</code>、<code>SAVEDATA</code>、<code>REF</code>、<code>DYNAMIC</code> 关键字同时使用。</p><p>数组的元素数也可以不省略，但如果元素数与初始值的个数不一致，就会发生错误。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;定义一维常量数组</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#569CD6;"> CONST </span><span style="color:#9CDCFE;">HOGE</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">;错误（初始值的个数与元素数不一致）</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#569CD6;"> CONST </span><span style="color:#9CDCFE;">PUGE</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">100</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 4</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">5</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">6</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">;字符串变量也可以（用字符串表达式指定）</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIMS</span><span style="color:#569CD6;"> CONST </span><span style="color:#9CDCFE;">SHOGE</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;A&quot;</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;B&quot;</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;C&quot;</span></span></code></pre></div><h2 id="引用型变量" tabindex="-1">引用型变量 <a class="header-anchor" href="#引用型变量" aria-label="Permalink to “引用型变量”">​</a></h2><p>在变量名前使用 <code>REF</code> 关键字可以定义引用型变量。</p><p>1 到 3 维的数值型和字符串型数组分别声明如下：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#569CD6;"> REF </span><span style="color:#9CDCFE;">HOGE1DIM</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#569CD6;"> REF </span><span style="color:#9CDCFE;">HOGE2DIM</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#569CD6;"> REF </span><span style="color:#9CDCFE;">HOGE3DIM</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIMS</span><span style="color:#569CD6;"> REF </span><span style="color:#9CDCFE;">PUGE1DIM</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIMS</span><span style="color:#569CD6;"> REF </span><span style="color:#9CDCFE;">PUGE2DIM</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIMS</span><span style="color:#569CD6;"> REF </span><span style="color:#9CDCFE;">PUGE3DIM</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">0</span></span></code></pre></div><p>有逗号时 <code>0</code> 可以省略，一维数组连逗号也可以省略。</p><p>引用型变量没有实体，操作引用型变量实际上就是操作通过 <code>REF</code> 指令（从 ver1.815 起不可用）或按引用传递进来的变量。</p><p>关于按引用传递的详情，请参阅<a href="./Function_and_Preprocessor.html">函数与预处理器</a>中的「按引用传递参数」。</p><h2 id="广域变量的书写格式" tabindex="-1">广域变量的书写格式 <a class="header-anchor" href="#广域变量的书写格式" aria-label="Permalink to “广域变量的书写格式”">​</a></h2><p>在<a href="./Header_File.html">头文件（ERH）</a>中书写 <code>#DIM(S)</code> 时，它不再是在 <code>ERB</code> 中定义的私有变量，而是可以从 <code>ERB</code> 任何位置引用的广域变量。</p><p>与私有变量不同，广域变量没有 <code>DYNAMIC</code> 与 <code>STATIC</code> 的区别，也不能用 <code>REF</code> 定义引用型变量，但可以用 <code>CONST</code> 以同样的方式定义常量。</p><p>在 ERH 中还可以定义 <code>DIM</code> 所没有的、面向函数的保存变量、广域变量和角色变量。</p><p>详情请参阅<a href="./Header_File.html">头文件（ERH）</a>。</p><h2 id="限制条件" tabindex="-1">限制条件 <a class="header-anchor" href="#限制条件" aria-label="Permalink to “限制条件”">​</a></h2><h3 id="不能使用与指令相同的名称" tabindex="-1">不能使用与指令相同的名称 <a class="header-anchor" href="#不能使用与指令相同的名称" aria-label="Permalink to “不能使用与指令相同的名称”">​</a></h3><p>不能定义与指令同名的变量，如下所示：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;报错</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> PRINTFORM</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> SELECTCASE</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> CALL</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> RETURN</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> GOTO</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> SQRT</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> DATAFORM</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> NOSKIP</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> FUNC</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> ENDFUNC</span></span></code></pre></div><p>可以定义与函数、预处理器同名的变量，但不推荐这样做。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;不推荐</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> EVENTFIRST</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> COMF32</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> COMABLE15</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> SHOW_ABLUP_SELECT</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> DIM</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> PRI</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> ONLY</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> SKIPSTART</span></span></code></pre></div><h3 id="函数外部的访问" tabindex="-1">函数外部的访问 <a class="header-anchor" href="#函数外部的访问" aria-label="Permalink to “函数外部的访问”">​</a></h3><p>与 <code>LOCAL@HOGE</code> 中的 <code>LOCAL</code> 不同，没有任何方法可以引用或赋值其他函数的私有变量。</p>`,53)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};